head.script:
scwin.screenId = "jldfil21103";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_applDd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("today")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Submit();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil21103.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_linkDisclsApplList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_linkDisclsApplList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_linkDisclsApplList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_linkDisclsApplList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.loadForm === 'function') { scwin.loadForm(r["subcomNm"], r["subcomIsurCd"], r["asstTotamtOvr10pctYn"]); } else { console.error('[sdd] 행 동작 미정의: scwin.loadForm (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.loadForm'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_linkDisclsApplList.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_goStatList_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goStatList_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goStatList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.goStatList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil21103.btn_goStatList_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_Remove_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Remove_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Remove_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.remove()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21103.btn_Remove_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Submit = async function () {
    const sbmOptions = {
        id: "tx_fn_Submit",
        method: "post",
        action: "/company/linkDisclsAppl.do",
        ref: "dma_SubmitReq",
        target: "dlt_linkDisclsApplList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil21103.tx_fn_Submit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.loadForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param subcomNm subcomIsurCd asstTotamtOvr10pctYn
 * @returns
 * @hidden N
*/
scwin.loadForm = function (subcomNm, subcomIsurCd, asstTotamtOvr10pctYn) {
    /* sdd-asis-lifecycle:begin fn_LoadForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.linkDisclsAppForm || { elements: [] });
    $c.util.getComponent('ipt_subcomNm').setValue(subcomNm);
    $c.util.getComponent('dma_SubmitReq').set('subcomIsurCd', subcomIsurCd);
    const obj = $c.util.getComponent('rd_asstTotamtOvr10pctYnSel');
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].value === asstTotamtOvr10pctYn) {
            obj[i].checked = true;
            break;
        }
    }
    $c.util.getComponent('dma_SubmitReq').set('asstTotamtOvr10pctYn', asstTotamtOvr10pctYn);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chk = async function () {
    /* sdd-asis-lifecycle:begin fn_Chk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.linkDisclsAppForm || { elements: [] });
    if ($c.util.getComponent('ipt_applDd').getValue()>= $c.util.getComponent('cal_lnkDisclsApplApplDd').getValue()) {
        await $c.win.alert('연계공시 적용신청일은  신청일보다 이후 일자 이어야 합니다.');
        $c.util.getComponent("cal_lnkDisclsApplApplDd").focus();
        return false;
    }
    if (($c.util.getComponent('cal_lnkDisclsApplApplDd').getValue() == null ? '' : String($c.util.getComponent('cal_lnkDisclsApplApplDd').getValue())) === '' || $c.util.getComponent('cal_lnkDisclsApplApplDd').getValue().indexOf(" ") === "") {
        await $c.win.alert("연계공시 적용신청일을 입력해 주세요");
        $c.util.getComponent("cal_lnkDisclsApplApplDd").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_subcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_subcomNm').getValue())) === '' || $c.util.getComponent('ipt_subcomNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("상장자회사를 입력해 주세요");
        $c.util.getComponent("ipt_subcomNm").focus();
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.remove = async function () {
    /* sdd-asis-lifecycle:begin fn_Remove — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.linkDisclsAppForm || { elements: [] });
    if (!await scwin.chk()) {
        return;
    }
    scwin.loadPop();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.submit
 * @author Inswave
 * @date 2026. 09. 29
 * @param type
 * @returns
 * @hidden N
*/
scwin.submit = async function (type) {
    /* sdd-asis-lifecycle:begin fn_Submit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ("rmv" !== type) {
        await $c.win.alert("잘못된 요청입니다. 다시 시도해주십시요");
        return false;
    }
    const frm = (document.linkDisclsAppForm || { elements: [] });
    $c.util.getComponent('dma_SubmitReq').set('method', 'removeLinkDisclsAppl');
    frm.action = 'linkDisclsAppl.do';
    await scwin.tx_fn_Submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goStatList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goStatList = function () {
    /* sdd-asis-lifecycle:begin fn_goStatList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const linkDisclsAppURL = '/jldfil21100/jldfil21100.xml';
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkDisclsAppURL));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.loadPop
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.loadPop = async function () {
    /* sdd-asis-lifecycle:begin fn_LoadPop — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const linkDisclsAppURL = '/jldfil21104/jldfil21104.xml?type=rmv';
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkDisclsAppURL), { id: "LinkDisclsNotice", scrollbars: false, resizable: false, width: "510", height: "730", type: "pageFramePopup" }, { method: "searchLinkDisclsApplList" });
    /* sdd-asis-lifecycle:end */
};
